solutions.naive:
class Solution:
    def minimumSize(self, nums, maxOperations):
        def ops(p):
            total = 0
            for x in nums:
                total += (x - 1) // p
            return total
        for p in range(1,max(nums)+1):
            if ops(p) <= maxOperations: return p
        return max(nums)

solutions.better:
class Solution:
    def minimumSize(self, nums, maxOperations):
        def ops(p):
            total = 0
            for x in nums:
                total += (x - 1) // p
            return total
        lo,hi,ans=1,max(nums),max(nums)
        while lo<=hi:
            mid=(lo+hi)//2
            if ops(mid)<=maxOperations: ans=mid; hi=mid-1
            else: lo=mid+1
        return ans

