class Solution:
    def minimumSize(self, nums, maxOperations):
        bags=len(nums)+maxOperations
        lo=max(1,(sum(nums)+bags-1)//bags); hi=max(nums)
        def can(p):
            used=0
            for x in nums:
                used += (x - 1) // p
                if used > maxOperations: return False
            return True
        while lo < hi:
            mid=(lo+hi)//2
            if can(mid): hi=mid
            else: lo=mid+1
        return lo

